    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int m = Integer.parseInt(st.nextToken());
        String[][] rates = new String[m][2];
        long[][] nums = new long[m][2];
        for (int i = 0; i < m; i++) {
            rates[i][0] = st.nextToken();
            rates[i][1] = st.nextToken();
            nums[i][0] = Long.parseLong(st.nextToken());
            nums[i][1] = Long.parseLong(st.nextToken());
        }
        int q = Integer.parseInt(st.nextToken());
        String[][] queries = new String[q][2];
        for (int i = 0; i < q; i++) {
            queries[i][0] = st.nextToken();
            queries[i][1] = st.nextToken();
        }
        long[] res = conversionRates(rates, nums, queries);
        StringBuilder sb = new StringBuilder();
        for (long x : res) sb.append(x).append("\n");
        System.out.print(sb);
    }
