def gen(rng):
    letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    def names(c, ln):
        s = set()
        while len(s) < c:
            s.add(''.join(rng.choice(letters) for _ in range(rng.randint(2, ln))))
        s = sorted(s)
        rng.shuffle(s)
        return s
    def fmt(edges, qs):
        return '\n'.join([str(len(edges))] + ['%s %s %d %d' % e for e in edges] + [str(len(qs))] + ['%s %s' % x for x in qs])
    def build(c, m, groups, vmax, kmax, ln, nq, shape='random'):
        nm = names(c + 3, ln)
        extra = nm[c:]
        nm = nm[:c]
        val = {x: rng.randint(1, vmax) for x in nm}
        grp = [nm[i::groups] for i in range(groups)]
        edges = []
        def add(a, b):
            k = rng.randint(1, kmax)
            e = (a, b, val[a] * k, val[b] * k)
            if rng.random() < 0.5:
                e = (b, a, val[b] * k, val[a] * k)
            edges.append(e)
        for g in grp:
            for i in range(1, len(g)):
                if shape == 'chain':
                    j = i - 1
                else:
                    j = rng.randrange(i)
                add(g[i], g[j])
        while len(edges) < m:
            g = rng.choice(grp)
            if len(g) >= 2:
                a, b = rng.sample(g, 2)
                add(a, b)
            else:
                break
        edges = edges[:max(m, 1)] if len(edges) > m else edges
        rng.shuffle(edges)
        qs = []
        allm = nm + extra
        for _ in range(nq):
            r = rng.random()
            if r < 0.05:
                a = rng.choice(allm)
                qs.append((a, a))
            else:
                qs.append((rng.choice(allm), rng.choice(allm)))
        return fmt(edges, qs)
    tests = [
        fmt([('USD', 'EUR', 9, 10)], [('USD', 'EUR'), ('EUR', 'USD'), ('USD', 'USD'), ('USD', 'GBP'), ('GBP', 'GBP')]),
        fmt([('A', 'B', 2, 1), ('B', 'C', 3, 1), ('A', 'C', 6, 1)], [('A', 'C'), ('C', 'A'), ('B', 'A')]),
        fmt([('A', 'B', 1, 1), ('C', 'D', 5, 3)], [('A', 'B'), ('A', 'C'), ('D', 'C'), ('C', 'D')]),
        fmt([('X', 'Y', 10**9, 1), ('Y', 'Z', 10**9, 1)], [('X', 'Z'), ('Z', 'X')]),
    ]
    for _ in range(30):
        c = rng.randint(2, 7)
        tests.append(build(c, rng.randint(c - 1, c + 3), rng.randint(1, 2), rng.choice([3, 12]), rng.choice([1, 4]), 2, rng.randint(2, 5)))
    tests.append(build(50000, 50000, 1, 10**9, 1, 4, 50000))
    tests.append(build(50000, 50000, 1, 1000, 10**6, 4, 50000, 'chain'))
    tests.append(build(30000, 50000, 5, 10**4, 10**5, 4, 50000))
    tests.append(build(25001, 50000, 1000, 10**9, 1, 4, 50000))
    return tests
